function patternHourglass(n) {
  let rows = [];
  // Top half
  for (let i = 0; i < n; i++) {
    let row = '';
    for (let j = 0; j < i; j++) row += ' ';
    for (let k = 0; k < 2 * (n - i) - 1; k++) row += '*';
    rows.push(row);
  }
  // Bottom half
  for (let i = 1; i < n; i++) {
    let row = '';
    for (let j = 0; j < n - 1 - i; j++) row += ' ';
    for (let k = 0; k < 2 * i + 1; k++) row += '*';
    rows.push(row);
  }
  return rows.join('\n');
}

