function patternHourglass(n) {
  let rows = [];
  for (let i = 0; i < n; i++) {
    rows.push(' '.repeat(i) + '*'.repeat(2 * (n - i) - 1));
  }
  for (let i = 1; i < n; i++) {
    rows.push(' '.repeat(n - 1 - i) + '*'.repeat(2 * i + 1));
  }
  return rows.join('\n');
}
